#include <stdio.h>
#include <stdlib.h>
/* ex06：SSTF（最短寻道时间优先）
 * 每次选「离当前磁头最近」的请求 -> 贪心。
 * 优点：总寻道距离明显小于 FCFS；缺点：远处的请求可能长期得不到服务（饥饿）。*/
int main(void) {
    int req[] = {98, 183, 37, 122, 14, 124, 65, 67};
    int n = (int)(sizeof(req) / sizeof(req[0]));
    int done[8] = {0};
    int head = 53, total = 0;

    printf("初始磁头=%d\n", head);
    printf("%-8s %-10s %s\n", "请求", "移动距离", "累计");
    for (int k = 0; k < n; k++) {
        int best = -1, bestd = 1 << 30;
        for (int i = 0; i < n; i++) {
            if (done[i]) continue;
            int d = abs(req[i] - head);
            if (d < bestd) { bestd = d; best = i; }
        }
        done[best] = 1;
        head = req[best];
        total += bestd;
        printf("%-8d %-10d %d\n", req[best], bestd, total);
    }
    printf("SSTF 总寻道距离 = %d 个磁道（FCFS 是 640，省 %.0f%%）\n",
           total, 100.0 * (640 - total) / 640);
    printf("注意：本序列恰好两端都会走到；构造「持续到达中间偏外侧请求」的场景时，\n");
    printf("      最内侧/最外侧的请求会被无限推迟 —— 这就是饥饿。\n");
    return 0;
}
